<template>
  <main class="assistant-page">
    <header class="assistant-header">
      <RouterLink to="/dashboard" class="back">← 返回功率监测</RouterLink>
      <div class="brand"><span class="brand-mark">✦</span><div><h1>智能调控中心</h1><small>AGENT ORCHESTRATION · POWER GRID CONTROL</small></div></div>
      <div class="header-tools"><button @click="newConversation">＋ 新建会话</button><button @click="clearConversation">清空</button><div class="header-state"><span class="state-dot" :class="{ ready: status?.ready }"></span>{{ status?.model_configured ? '模型已连接' : '规则引擎在线' }}</div></div>
    </header>
    <section class="assistant-layout">
      <aside class="control-rail">
        <div class="digital-human">
          <div class="halo halo-a"></div><div class="halo halo-b"></div>
          <img class="avatar-core" src="/assets/dispatch-assistant.png" alt="电力数字能量体" />
          <span class="avatar-status">调控智能体 · 在线</span>
        </div>
        <div class="scope-box"><label>分析场站</label><select v-model="stationId"><option :value="null">全场场站</option><option v-for="station in stations" :key="station.station_id" :value="station.station_id">{{ station.station_id }}</option></select></div>
        <div class="agent-list"><div v-for="agent in status?.agents || defaultAgents" :key="agent" class="agent-item"><span>●</span><div><strong>{{ agent }}</strong><small>{{ agent === '实时数据智能体' ? '功率 · 气象 · 限电标记' : agent === '知识检索智能体' ? `${status?.document_count || 0} 条知识文档` : '等待任务' }}</small></div></div></div>
        <div class="session-history"><div class="history-title"><span>最近会话</span><button @click="exportConversation">导出当前</button></div><div v-for="session in sessions" :key="session.id" class="history-item" :class="{ current: session.id === currentSessionId }" @click="restoreSession(session)"><input v-if="editingSessionId === session.id" v-model="editingTitle" @click.stop @keydown.enter.prevent="saveSessionTitle(session)" @keydown.esc="cancelSessionRename" @blur="saveSessionTitle(session)" /><span v-else>{{ session.title }}</span><div class="history-actions"><button v-if="editingSessionId !== session.id" title="重命名" @click.stop="startSessionRename(session)">✎</button><button title="删除" @click.stop="deleteSession(session.id)">×</button></div></div><div v-if="!sessions.length" class="history-empty">暂无历史会话</div></div>
      </aside>
      <section class="conversation">
        <div class="conversation-title"><div><span>CONTROL ROOM · {{ currentSessionTitle }}</span><h2>让智能体理解现场，再给出调控动作</h2><p>可直接询问消纳、限电、并网风险、预测偏差和气象影响。</p></div><div class="live-pill">实时数据已接入</div></div>
        <div class="quick-actions"><button v-for="prompt in prompts" :key="prompt" @click="ask(prompt)">{{ prompt }}</button></div>
        <div class="workspace-kpis">
          <div class="workspace-kpi"><small>当前有功功率</small><strong>{{ livePower }}</strong><em>MW</em><span>实时汇总 · {{ onlineCount }}/{{ platformStore.overview.count || stations.length }} 在线</span></div>
          <div class="workspace-kpi"><small>新能源消纳率</small><strong>{{ consumptionRate }}</strong><em>%</em><span>当前分析范围 · {{ stationLabel }}</span></div>
          <div class="workspace-kpi"><small>数据新鲜度</small><strong class="fresh">{{ dataFreshness }}</strong><span>{{ lastObserved }}</span></div>
        </div>
        <div ref="messagesEl" class="messages">
          <div class="message agent"><div class="mini-avatar">✦</div><div><small>调控智能体 · 已准备</small><p>我可以读取当前场站功率、理论功率、可利用功率、限电标记和测风塔/辐照度观测，再结合知识库给出调控建议。请告诉我你要分析的场站或目标。</p></div></div>
          <div v-for="(message, index) in messages" :key="message.id" class="message" :class="message.role"><div v-if="message.role === 'agent'" class="mini-avatar">✦</div><div class="message-body"><small>{{ message.role === 'user' ? '你' : `调控智能体 · ${message.mode || '分析完成'}` }}</small><div class="message-content" v-html="renderMessage(message.text)"></div><details v-if="message.role === 'agent' && (message.steps?.length || message.sources?.length)" class="evidence-trace"><summary>查看完整分析过程与证据 <span>{{ message.sources?.length || 0 }} 条依据</span></summary><div class="trace-note">展开查看可审计的意图识别、数据选择、时间校验、智能体步骤、知识依据、风险判断和建议来源；不展示未经整理的模型私有思维链。</div><div class="trace-section"><strong>分析框架</strong><div class="analysis-checks"><span>✓ 意图识别</span><span>✓ 实时数据读取</span><span>✓ 时间口径校验</span><span>✓ 安全约束检查</span></div></div><div v-if="message.sources?.length" class="trace-section"><strong>知识依据 / 公开来源</strong><div class="source-list"><div v-for="source in message.sources" :key="source.source_id" class="source-item"><a v-if="source.source_id.startsWith('http')" :href="source.source_id" target="_blank">{{ source.title || source.source_id }}</a><b v-else>{{ source.title || '知识库依据' }} · {{ source.source_id }}</b><p v-if="source.excerpt">{{ source.excerpt }}</p></div></div></div><div v-if="message.steps?.length" class="trace-section"><strong>智能体过程摘要</strong><div class="steps"><span v-for="step in message.steps" :key="step.agent" :class="step.status">{{ step.agent }} <b>{{ step.status === 'done' ? '完成' : step.status === 'empty' ? '未命中' : '规则模式' }}</b><small>{{ step.detail }}</small></span></div></div></details><div v-if="message.role === 'agent' && message.text" class="message-actions"><button @click="copyMessage(message.text)">复制</button><button @click="regenerate(index)">重新生成</button><button :class="{ selected: message.rating === 'up' }" @click="rateMessage(message,'up')">有帮助</button><button :class="{ selected: message.rating === 'down' }" @click="rateMessage(message,'down')">需改进</button></div></div></div>
          <div v-if="loading" class="typing"><span></span><span></span><span></span>智能体正在读取实时数据并组织建议…</div>
        </div>
        <form class="composer" @submit.prevent="submit"><div class="mode-bar"><button type="button" class="mode-chip always-on" disabled title="实时数据始终接入"><span>⚡ 实时数据</span><em>常开</em></button><button type="button" class="mode-chip toggle-chip" :class="{ selected: deepMode }" :aria-pressed="deepMode" @click="deepMode = !deepMode"><span>✦ 深度调控</span><em>{{ deepMode ? '开' : '关' }}</em></button><button type="button" class="mode-chip toggle-chip" :class="{ selected: knowledgeMode }" :aria-pressed="knowledgeMode" @click="knowledgeMode = !knowledgeMode"><span>⌘ 知识检索</span><em>{{ knowledgeMode ? '开' : '关' }}</em></button><button type="button" class="mode-chip toggle-chip" :class="{ selected: webSearchMode }" :aria-pressed="webSearchMode" @click="webSearchMode = !webSearchMode"><span>◎ 联网搜索</span><em>{{ webSearchMode ? '开' : '关' }}</em></button><button type="button" class="mode-chip attachment-action" @click="fileInput?.click()">＋ 添加资料</button><input ref="fileInput" type="file" hidden accept=".txt,.md,.csv,.json,.pdf" @change="handleAttachment" /><span v-if="attachment" class="attachment-pill">{{ attachment }} <button type="button" @click="attachment = ''; attachmentContent = ''">×</button></span></div><div class="composer-main"><textarea v-model="question" rows="2" @keydown.enter.exact.prevent="submit" placeholder="输入场站、功率、气象或调控问题…（Enter 发送，Shift+Enter 换行）" :disabled="loading"></textarea><button v-if="loading" type="button" class="stop-button" @click="stopGeneration">停止生成</button><button v-else :disabled="!question.trim()">发送 <span>↗</span></button></div><div class="composer-foot"><span>{{ webSearchMode ? '已开启联网搜索，公开网页来源将加入证据链' : '回答会结合实时功率、气象、限电标记与知识库证据' }}</span><span>Enter 发送 · Shift+Enter 换行</span></div></form>
      </section>
      <aside class="insight-rail">
        <div class="insight-card decision-card"><div class="insight-label"><i></i>调控工作台</div><h3>{{ stationLabel }}</h3><p>先分析，再建议，最后确认。当前仅输出辅助决策，不直接下发指令。</p><div class="decision-status"><span></span>安全约束优先</div></div>
        <div class="insight-card"><div class="insight-label">实时信号 · 当前口径</div><div class="signal-row"><span>当前有功功率</span><b>{{ livePower }} MW</b></div><div class="signal-help">{{ stationLabel }} · {{ lastObserved }}</div><div class="signal-row"><span>{{ signalConsumptionLabel }}</span><b>{{ signalConsumptionRate }}</b></div><div class="signal-help">{{ signalConsumptionScope }}</div><div class="signal-row"><span>{{ stationId ? '限电标记（当前场站）' : '限电标记（全场）' }}</span><b>{{ limitStatus }}</b></div><div class="signal-help">来自各场站最新实时快照</div><div class="signal-row"><span>数据来源</span><b>功率 / 气象实时接口</b></div></div>
        <div class="insight-card evidence-card"><div class="insight-label">决策链路</div><div class="chain-step" v-for="(item, index) in ['读取功率 / 气象上下文','检索调控规程与案例','评估消纳收益与安全边界','生成可审计建议']" :key="item"><i>{{ index + 1 }}</i><span>{{ item }}</span></div></div>
        <div class="insight-card guard-card"><div class="insight-label">执行边界</div><p>建议需要人工确认后执行；系统会保留问题、实时数据、知识证据和反馈结果。</p><button @click="question = `请对${stationLabel}给出一份带风险边界和验证指标的调控建议`; submit()">生成调控建议 ↗</button></div>
      </aside>
    </section>
  </main>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { platformApi } from '../../api/platform'
import type { AssistantResponse, AssistantStep, ConsumptionOverview, Station } from '../../api/types'
import { usePlatformStore } from '../../stores/platform'
const platformStore = usePlatformStore()
const stations = ref<Station[]>([]), status = ref<{ ready: boolean; document_count: number; model_configured: boolean; agents: string[] } | null>(null), consumption = ref<ConsumptionOverview | null>(null), stationId = ref<string | null>(null), question = ref(''), loading = ref(false), messagesEl = ref<HTMLElement | null>(null), fileInput = ref<HTMLInputElement | null>(null), attachment = ref(''), deepMode = ref(false)
const knowledgeMode = ref(true), webSearchMode = ref(false), attachmentContent = ref(''), attachmentStatus = ref('')
const defaultAgents = ['问题理解智能体', '实时数据智能体', '知识检索智能体', '报告生成智能体']
const prompts = ['分析当前全场消纳状态', 'FD0001 是否存在限电风险？', '结合气象给出并网建议', '为什么预测和实际有偏差？']
type ChatMessage = { id: number; role: 'user' | 'agent'; text: string; mode?: string; steps?: AssistantStep[]; sources?: AssistantResponse['sources']; confidence?: string; rating?: 'up' | 'down' }
type ChatSession = { id: number; title: string; messages: ChatMessage[]; stationId: string | null }
const messages = ref<ChatMessage[]>([])
const sessions = ref<ChatSession[]>([])
const currentSessionId = ref<number | null>(null), editingSessionId = ref<number | null>(null), editingTitle = ref('')
let messageSequence = 1
const stopRequested = ref(false)
let assistantRefreshTimer: number | undefined
const selectedSnapshot = computed(() => platformStore.overview.stations.find((item) => item.station_id === stationId.value) || null)
const livePower = computed(() => selectedSnapshot.value?.active_power_mw != null ? selectedSnapshot.value.active_power_mw.toFixed(2) : platformStore.overview.stations.reduce((sum, item) => sum + (item.active_power_mw || 0), 0).toFixed(2))
const onlineCount = computed(() => platformStore.overview.stations.filter((item) => item.freshness === 'realtime' || item.freshness === 'near_realtime').length)
const stationLabel = computed(() => stationId.value || '全场场站')
const currentSessionTitle = computed(() => sessions.value.find((session) => session.id === currentSessionId.value)?.title || '新会话')
const consumptionRate = computed(() => { const value = stationId.value ? consumption.value?.station_breakdown?.find((item) => item.station_id === stationId.value)?.consumption_rate : consumption.value?.consumption_rate; return value == null ? '—' : value.toFixed(1) })
const selectedConsumptionRow = computed(() => stationId.value ? consumption.value?.station_breakdown?.find((item) => item.station_id === stationId.value) : null)
const signalConsumptionLabel = computed(() => selectedConsumptionRow.value?.consumption_rate != null ? '当前场站消纳率' : '全场消纳率')
const signalConsumptionRate = computed(() => { const value = selectedConsumptionRow.value?.consumption_rate ?? consumption.value?.consumption_rate; return value == null ? '读取中' : `${value.toFixed(1)}%` })
const signalConsumptionScope = computed(() => selectedConsumptionRow.value?.consumption_rate != null ? `${stationLabel.value} 最新实时统计` : '全场最新实时统计')
const dataFreshness = computed(() => platformStore.overview.updated_at ? '实时' : '等待接入')
const lastObserved = computed(() => selectedSnapshot.value?.observed_at ? `观测 ${new Date(selectedSnapshot.value.observed_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}` : '正在读取最新快照')
const limitStatus = computed(() => { if (stationId.value) return selectedSnapshot.value?.limit_mark === 1 ? '限电（1）' : '不限电（0）'; const marked = platformStore.overview.stations.filter((item) => item.limit_mark === 1).length; const total = platformStore.overview.stations.length; return `限电 ${marked} · 不限电 ${Math.max(0, total - marked)}` })
function escapeHtml(value: string) { return value.replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char] || char)) }
function renderMessage(value: string) {
  const labels: Record<string, string> = { observed_at: '观测时间', available: '数据可用', freshness: '新鲜度', active_power_mw: '实时功率', theory_power_mw: '理论功率', available_power_mw: '可利用功率', limit_mark: '限电标记', wind_speed_ms: '风速', wind_direction_deg: '风向', temperature_c: '温度', humidity_pct: '湿度', pressure_hpa: '气压', ghi_wm2: '辐照度' }
  let normalized = value.replace(/\bNone\b/g, '暂无').replace(/\bTrue\b/g, '是').replace(/\bFalse\b/g, '否')
  Object.entries(labels).forEach(([key, label]) => { normalized = normalized.replace(new RegExp(`\\b${key}\\b`, 'g'), label) })
  Object.values(labels).forEach((label) => { normalized = normalized.replace(new RegExp(`${label}\\s*[=:]\\s*`, 'g'), `${label}：`) })
  normalized = normalized.replace(/限电标记\s*[=:]\s*0/g, '限电标记：否').replace(/限电标记\s*[=:]\s*1/g, '限电标记：是')
  const inline = (line: string) => escapeHtml(line).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/`([^`]+)`/g, '<code>$1</code>')
  const output: string[] = []; let listOpen = false
  normalized.split(/\r?\n/).forEach((line) => {
    const text = line.trim()
    if (!text) { if (listOpen) { output.push('</ul>'); listOpen = false }; return }
    if (/^```/.test(text)) { output.push(`<pre>${inline(text.replace(/^```/, ''))}</pre>`); return }
    if (/^(#{1,4}\s|[一二三四五六七八九十]+、)/.test(text)) { if (listOpen) { output.push('</ul>'); listOpen = false }; output.push(`<h4>${inline(text.replace(/^#{1,4}\s*/, '') )}</h4>`); return }
    if (/^[-•]\s+/.test(text) || /^\d+[.)]\s+/.test(text)) { if (!listOpen) { output.push('<ul>'); listOpen = true }; output.push(`<li>${inline(text.replace(/^([-•]|\d+[.)])\s+/, ''))}</li>`); return }
    if (listOpen) { output.push('</ul>'); listOpen = false }
    output.push(`<p>${inline(text)}</p>`)
  })
  if (listOpen) output.push('</ul>')
  return output.join('')
}
async function streamText(message: ChatMessage, answer: string) { for (let index = 0; index < answer.length; index += 5) { if (stopRequested.value) break; message.text += answer.slice(index, index + 5); await new Promise((resolve) => window.setTimeout(resolve, 12)); await nextTick(); messagesEl.value?.scrollTo({ top: messagesEl.value.scrollHeight }) } if (stopRequested.value && !message.text) message.text = '已停止生成。' }
async function submit() { const raw = question.value.trim(); if (!raw || loading.value) return; let value = raw; if (deepMode.value) value = `请使用深度调控模式，展开安全约束、证据和验证指标：${value}`; if (!knowledgeMode.value) value = `仅依据实时数据回答，不引用知识库：${value}`; if (attachmentContent.value) value += `\n附加资料：${attachmentContent.value.slice(0, 4000)}`; const history = messages.value.slice(-8).map((item) => ({ role: item.role, content: item.text })); question.value = ''; messages.value.push({ id: messageSequence++, role: 'user', text: raw }); loading.value = true; stopRequested.value = false; try { const result = await platformApi.assistantChat(value, stationId.value, webSearchMode.value, history); const message: ChatMessage = { id: messageSequence++, role: 'agent', text: '', mode: result.mode, steps: result.steps, sources: result.sources, confidence: result.confidence }; messages.value.push(message); const live = result.live_context || {}; const safeAnswer = result.answer?.trim() || `已读取实时运行数据：当前在线 ${live.online ?? '—'}/${live.total ?? '—'} 个场站，总有功功率 ${live.total_active_power_mw ?? '—'} MW。模型报告生成暂时返回空内容，已保留实时数据和调控链路，请稍后重试。`; await streamText(message, safeAnswer); saveCurrentSession() } catch (error: any) { const detail = error?.response?.data?.detail; messages.value.push({ id: messageSequence++, role: 'agent', text: detail ? `请求未通过：${detail}` : '智能调控接口暂时不可用，请检查后端服务；当前没有输出未经核验的控制指令。', mode: 'offline' }) } finally { loading.value = false; stopRequested.value = false; await nextTick(); messagesEl.value?.scrollTo({ top: messagesEl.value.scrollHeight, behavior: 'smooth' }) } }
function ask(value: string) { question.value = value; submit() }
function stopGeneration() { stopRequested.value = true }
function copyMessage(value: string) { navigator.clipboard?.writeText(value) }
function rateMessage(message: ChatMessage, rating: 'up' | 'down') { message.rating = message.rating === rating ? undefined : rating }
function regenerate(index: number) { const previous = messages.value.slice(0, index).reverse().find((message) => message.role === 'user'); if (previous) { question.value = previous.text; submit() } }
function newConversation() { saveCurrentSession(); messages.value = []; question.value = ''; currentSessionId.value = null; stopRequested.value = false }
function clearConversation() { messages.value = [] }
async function handleAttachment(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; attachment.value = file?.name || ''; attachmentContent.value = ''; attachmentStatus.value = ''; if (!file) return; attachmentStatus.value = '正在解析…'; try { const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ''; const chunk = 0x8000; for (let index = 0; index < bytes.length; index += chunk) binary += String.fromCharCode(...bytes.subarray(index, Math.min(index + chunk, bytes.length))); const parsed = await platformApi.parseAttachment(file.name, file.type || 'application/octet-stream', btoa(binary)); attachmentContent.value = parsed.text; attachmentStatus.value = `已解析 ${parsed.characters} 字`; } catch (error: any) { attachmentStatus.value = `解析失败：${error?.response?.data?.detail || '请更换文件'}` } finally { input.value = '' } }
function saveCurrentSession() { const first = messages.value.find((item) => item.role === 'user'); if (!first) return; const existing = sessions.value.find((item) => item.id === currentSessionId.value); const id = existing?.id || Date.now(); const session = { id, title: existing?.title || first.text.slice(0, 24), messages: JSON.parse(JSON.stringify(messages.value)), stationId: stationId.value }; currentSessionId.value = id; sessions.value = [session, ...sessions.value.filter((item) => item.id !== id)].slice(0, 8); localStorage.setItem('assistant-sessions', JSON.stringify(sessions.value)) }
function restoreSession(session: ChatSession) { messages.value = JSON.parse(JSON.stringify(session.messages)); stationId.value = session.stationId; currentSessionId.value = session.id; editingSessionId.value = null }
function startSessionRename(session: ChatSession) { editingSessionId.value = session.id; editingTitle.value = session.title }
function cancelSessionRename() { editingSessionId.value = null; editingTitle.value = '' }
function saveSessionTitle(session: ChatSession) { const title = editingTitle.value.trim(); if (title) session.title = title; localStorage.setItem('assistant-sessions', JSON.stringify(sessions.value)); cancelSessionRename() }
function deleteSession(id: number) { sessions.value = sessions.value.filter((session) => session.id !== id); if (currentSessionId.value === id) { currentSessionId.value = null; messages.value = [] }; localStorage.setItem('assistant-sessions', JSON.stringify(sessions.value)) }
function exportConversation() { const text = messages.value.map((item) => `${item.role === 'user' ? '用户' : '调控智能体'}：\n${item.text}`).join('\n\n'); const blob = new Blob([text || '暂无对话内容'], { type: 'text/plain;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `调控会话-${new Date().toISOString().slice(0,10)}.txt`; link.click(); URL.revokeObjectURL(link.href) }
onMounted(async () => { try { sessions.value = JSON.parse(localStorage.getItem('assistant-sessions') || '[]') } catch { sessions.value = [] } const [s, a, o, c] = await Promise.allSettled([platformApi.stations(), platformApi.assistantStatus(), platformStore.loadOverview(), platformApi.consumption()]); if (s.status === 'fulfilled') stations.value = s.value; if (a.status === 'fulfilled') status.value = a.value; if (c.status === 'fulfilled') consumption.value = c.value; platformStore.connectRealtime(); assistantRefreshTimer = window.setInterval(() => { platformApi.consumption().then((value) => { consumption.value = value }).catch(() => undefined) }, 15000) })
onUnmounted(() => { platformStore.disconnectRealtime(); if (assistantRefreshTimer) window.clearInterval(assistantRefreshTimer) })
